'use strict';

const STORAGE_KEY = 'todos-vanillajs';
const ENTER_KEY = 13;

const $todoInput = document.querySelector('.new-todo');
const $main = document.querySelector('.main');
const $footer = document.querySelector('.footer');
const $list = document.querySelector('.todo-list');
const $toggleAll = document.querySelector('#toggle-all');
const $clearCompleted = document.querySelector('.clear-completed');
const $count = document.querySelector('.todo-count');
const $filters = document.querySelector('.filters');

let todos = [];
let editingId = null;

/**
 * Reads the persisted todo list from localStorage.
 * @planks("the app is loaded with no todos")
 * @planks("the app is loaded with todos:")
 * @planks("the app has {int} active todos")
 * @planks("the user reloads the app")
 * @planks("^the todo list has (\d+) items?$")
 * @planks-provisional("features/@captain-persistence-edge.feature:Corrupt localStorage JSON loads as an empty list")
 */
function loadTodos() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    todos = Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    todos = [];
  }
}

/**
 * Persists the current todo list to localStorage.
 * @planks("the {string} localStorage entry is a JSON array")
 * @planks("^each stored todo has the fields (.+)$")
 */
function saveTodos() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
}

/**
 * Generates a unique id for a new todo (preserved as the persisted `id` field).
 * @planks("^each stored todo has the fields (.+)$")
 */
function uuid() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

/**
 * Resolves the active route filter from the location hash.
 * @planks("the user opens the {string} filter")
 * @planks("the {string} filter link is selected")
 * @planks("the {string} filter link is not selected")
 */
function getFilter() {
  const hash = (location.hash || '').replace(/^#\/?/, '');
  if (hash === 'active') return 'active';
  if (hash === 'completed') return 'completed';
  return 'all';
}

/**
 * Creates a new todo from a trimmed, non-empty title.
 * @planks("the user types {string} into the new todo input")
 * @planks("the user presses Enter")
 */
function createTodo(title) {
  const trimmed = (title || '').trim();
  if (trimmed === '') return;
  todos.push({ id: uuid(), title: trimmed, completed: false });
  saveTodos();
  render();
}

/**
 * Toggles a single todo's completed state by id.
 * @planks("the user toggles the todo {string}")
 * @planks("the todo {string} is marked completed")
 */
function toggleTodo(id, completed) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) return;
  todo.completed = completed;
  saveTodos();
  render();
}

/**
 * Sets every todo to the same completed state.
 * @planks("the user marks all todos as complete")
 */
function toggleAll(completed) {
  todos.forEach((t) => {
    t.completed = completed;
  });
  saveTodos();
  render();
}

/**
 * Removes completed todos from the model.
 * @planks("the user clears completed todos")
 */
function clearCompleted() {
  todos = todos.filter((t) => !t.completed);
  saveTodos();
  render();
}

/**
 * Commits an edited title, or discards the edit when requested.
 * @planks("the user double-clicks the todo {string}")
 * @planks("the user edits the title to {string} and presses Enter")
 * @planks("the user edits the title to {string} and blurs the field")
 * @planks("the user edits the title to {string} and presses Escape")
 * @planks("the todo {string} is in edit mode")
 * @planks("the todo {string} is not in edit mode")
 */
function commitEdit(id, value, discard) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) return;
  editingId = null;
  if (discard) {
    render();
    return;
  }
  const trimmed = (value || '').trim();
  if (trimmed === '') {
    todos = todos.filter((t) => t.id !== id);
  } else {
    todo.title = trimmed;
  }
  saveTodos();
  render();
}

/**
 * Builds a list row element for a todo, wiring its event handlers once.
 * Rows are created once and then kept in place across renders, keyed by todo id.
 */
function createRow(todo) {
  const li = document.createElement('li');
  li.dataset.id = todo.id;

  const view = document.createElement('div');
  view.className = 'view';
  const toggle = document.createElement('input');
  toggle.className = 'toggle';
  toggle.type = 'checkbox';
  const label = document.createElement('label');
  const destroy = document.createElement('button');
  destroy.className = 'destroy';
  view.appendChild(toggle);
  view.appendChild(label);
  view.appendChild(destroy);

  const edit = document.createElement('input');
  edit.className = 'edit';

  li.appendChild(view);
  li.appendChild(edit);

  toggle.addEventListener('change', () => toggleTodo(todo.id, toggle.checked));
  label.addEventListener('dblclick', () => {
    editingId = todo.id;
    li.classList.add('editing');
    edit.value = todo.title;
    edit.focus();
  });
  destroy.addEventListener('click', () => {
    todos = todos.filter((t) => t.id !== todo.id);
    saveTodos();
    render();
  });
  edit.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      commitEdit(todo.id, edit.value, false);
    } else if (e.key === 'Escape') {
      commitEdit(todo.id, edit.value, true);
    }
  });
  edit.addEventListener('blur', () => commitEdit(todo.id, edit.value, false));

  return li;
}

/**
 * Syncs an existing row element to the current model and route state.
 * The row element itself is preserved; only its contents and state change.
 */
function updateRow(li, todo, filter) {
  li.classList.toggle('completed', todo.completed);
  li.classList.toggle('editing', editingId === todo.id);
  li.querySelector('.toggle').checked = todo.completed;
  li.querySelector('label').textContent = todo.title;
  if (editingId !== todo.id) {
    li.querySelector('.edit').value = todo.title;
  }
  if (filter === 'active' && todo.completed) li.hidden = true;
  else if (filter === 'completed' && !todo.completed) li.hidden = true;
  else li.hidden = false;
}

/**
 * Renders the list and chrome from the current model and route.
 * @planks("the todo list shows {string}")
 * @planks("the todo list does not show {string}")
 * @planks("^the todo list has (\d+) items?$")
 * @planks("the main section is hidden")
 * @planks("the footer is hidden")
 * @planks("the remaining count reads {string}")
 * @planks("the clear-completed button is hidden")
 * @planks("the clear-completed button is visible")
 * @planks("the mark-all control is checked")
 * @planks("the mark-all control is unchecked")
 * @planks("every todo is marked completed")
 * @planks-provisional("features/@captain-deleting-todos.feature:Deleting a todo removes it from the list")
 * @planks-provisional("features/@captain-list-state.feature:Mark-all control is indeterminate when only some todos are complete")
 */
function render() {
  const filter = getFilter();
  const seen = new Set();
  todos.forEach((todo) => {
    let li = $list.querySelector('li[data-id="' + String(todo.id) + '"]');
    if (!li) {
      li = createRow(todo);
      $list.appendChild(li);
    }
    updateRow(li, todo, filter);
    seen.add(String(todo.id));
  });
  Array.prototype.forEach.call($list.querySelectorAll('li'), (li) => {
    if (!seen.has(li.dataset.id)) li.remove();
  });

  const hasTodos = todos.length > 0;
  if (hasTodos) {
    $main.removeAttribute('hidden');
    $footer.removeAttribute('hidden');
  } else {
    $main.setAttribute('hidden', '');
    $footer.setAttribute('hidden', '');
  }

  const active = todos.filter((t) => !t.completed).length;
  const word = active === 1 ? 'item' : 'items';
  $count.innerHTML = '<strong>' + active + '</strong> ' + word + ' left';

  const completedCount = todos.filter((t) => t.completed).length;
  if (completedCount > 0) $clearCompleted.removeAttribute('hidden');
  else $clearCompleted.setAttribute('hidden', '');

  $toggleAll.checked = hasTodos && active === 0;
  $toggleAll.indeterminate = active > 0 && active < todos.length;

  const current = getFilter();
  Array.prototype.forEach.call($filters.querySelectorAll('a'), (a) => {
    const href = (a.getAttribute('href') || '').replace(/^#\/?/, '');
    const f = href === '' ? 'all' : href;
    if (f === current) a.classList.add('selected');
    else a.classList.remove('selected');
  });
}

/**
 * Applies the active route filter and updates the selected link.
 * @planks("the user opens the {string} filter")
 * @planks("the {string} filter link is selected")
 * @planks("the {string} filter link is not selected")
 */
function applyFilter() {
  render();
}

/** @planks("the new todo input is empty") */
$todoInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
    createTodo($todoInput.value);
    $todoInput.value = '';
  }
});

$toggleAll.addEventListener('change', () => toggleAll($toggleAll.checked));
$clearCompleted.addEventListener('click', clearCompleted);
window.addEventListener('hashchange', applyFilter);

loadTodos();
/** @planks("the new todo input is focused") */
$todoInput.focus();
render();

