import { Window } from 'happy-dom';
import fs from 'node:fs';
import path from 'node:path';
import { setWorldConstructor } from '@cucumber/cucumber';

const ROOT = process.cwd();
const INDEX = path.join(ROOT, 'index.html');
const APP = path.join(ROOT, 'js', 'app.js');
const CSS = path.join(ROOT, 'css', 'app.css');
const STORAGE_KEY = 'todos-vanillajs';

function cleanBody(html) {
  let h = html.replace(/<script[\s\S]*?<\/script>/g, '');
  h = h.replace(/<link[^>]*>/g, '');
  const m = h.match(/<body[^>]*>([\s\S]*)<\/body>/i);
  return m ? m[1] : h;
}

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this._savedStorage = undefined;
    this._savedHash = '';
  }

  freshWindow(persist = false) {
    if (persist) {
      this._savedStorage = this.window ? this.window.localStorage.getItem(STORAGE_KEY) : null;
      this._savedHash = this.window ? this.window.location.hash : '';
    } else {
      this._savedStorage = undefined;
      this._savedHash = '';
    }
    const url = 'http://localhost/' + (persist ? this._savedHash : '');
    const window = new Window({ url });
    if (persist && this._savedStorage != null) {
      window.localStorage.setItem(STORAGE_KEY, this._savedStorage);
    }
    this.window = window;
    this.document = window.document;
    return window;
  }

  mount({ seed = undefined } = {}) {
    if (!this.window) this.freshWindow(false);
    if (seed !== undefined) {
      if (seed === null) this.window.localStorage.removeItem(STORAGE_KEY);
      else this.window.localStorage.setItem(STORAGE_KEY, JSON.stringify(seed));
    }
    const bodyHtml = cleanBody(fs.readFileSync(INDEX, 'utf8'));
    this.document.body.innerHTML = bodyHtml;
    // Load the app's own stylesheet so behaviour pinned to css/app.css (e.g.
    // hiding the checkbox/destroy control while a row is edited) is observable.
    const style = this.document.createElement('style');
    style.textContent = fs.readFileSync(CSS, 'utf8');
    (this.document.head || this.document.body).appendChild(style);
    const appSrc = fs.readFileSync(APP, 'utf8');
    this.window.eval(appSrc);
  }

  loadApp(todos) {
    this.freshWindow(false);
    this.mount({ seed: todos });
  }

  reloadApp() {
    this.freshWindow(true);
    this.mount({});
  }

  newTodoInput() {
    return this.document.querySelector('.new-todo');
  }

  todoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  liByTitle(title) {
    return (
      this.todoItems().find(
        (li) => (li.querySelector('label')?.textContent || '').trim() === title,
      ) || null
    );
  }

  todoVisible(title) {
    return this.todoItems().some((li) => {
      const lbl = li.querySelector('label')?.textContent || '';
      return lbl.trim() === title && !li.hasAttribute('hidden');
    });
  }

  filterLink(name) {
    return (
      Array.from(this.document.querySelectorAll('.filters a')).find(
        (a) => a.textContent.trim() === name,
      ) || null
    );
  }
}

setWorldConstructor(TodoWorld);

import { Given, When, Then } from '@cucumber/cucumber';

// ----- Background / loading -----

Given('the app is loaded with no todos', function () {
  this.loadApp(null);
});

Given('the app is loaded with todos:', function (dataTable) {
  const rows = dataTable.hashes();
  const todos = rows.map((r, i) => ({
    id: i + 1,
    title: r.title,
    completed: r.completed === 'true',
  }));
  this.loadApp(todos);
});

Given('the app has {int} active todos', function (count) {
  const todos = [];
  for (let i = 0; i < count; i++) {
    todos.push({ id: i + 1, title: `Todo ${i + 1}`, completed: false });
  }
  this.loadApp(todos);
});

// ----- Creating todos -----

When('the user types {string} into the new todo input', function (text) {
  const input = this.newTodoInput();
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the user presses Enter', function () {
  const input = this.newTodoInput();
  input.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }),
  );
});

Then('the todo list shows {string}', function (title) {
  if (!this.todoVisible(title)) {
    throw new Error(`Todo list does not show "${title}"`);
  }
});

Then('the todo list does not show {string}', function (title) {
  if (this.todoVisible(title)) {
    throw new Error(`Todo list shows "${title}" but should not`);
  }
});

Then(/^the todo list has (\d+) items?$/, function (n) {
  const count = parseInt(n, 10);
  const found = this.todoItems().length;
  if (found !== count) {
    throw new Error(`Expected ${count} item(s), found ${found}`);
  }
});

Then('the new todo input is empty', function () {
  const input = this.newTodoInput();
  if (input.value !== '') {
    throw new Error(`New todo input is not empty: "${input.value}"`);
  }
});

Then('the new todo input is focused', function () {
  if (this.document.activeElement !== this.newTodoInput()) {
    throw new Error('New todo input is not focused');
  }
});

// ----- Completing todos -----

Given('the todo {string} is marked completed', function (title) {
  // The spec reuses this phrase as both a Given precondition (ensure the todo is
  // completed) and a Then assertion. Implemented as the real UI action that drives
  // the todo to the completed state; on the success path of a Then this is a no-op
  // and the subsequent assertion holds.
  let li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  const toggle = li.querySelector('.toggle');
  if (!toggle.checked) {
    toggle.checked = true;
    toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    li = this.liByTitle(title); // re-query: the app re-renders on change
  }
  if (!li || !li.classList.contains('completed')) {
    throw new Error(`Todo "${title}" not marked completed`);
  }
});

When('the user toggles the todo {string}', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  this._rowsBefore = { [title]: li };
  const toggle = li.querySelector('.toggle');
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user marks all todos as complete', function () {
  this._rowsBefore = {};
  for (const li of this.todoItems()) {
    const lbl = li.querySelector('label')?.textContent?.trim();
    if (lbl) this._rowsBefore[lbl] = li;
  }
  const mark = this.document.querySelector('#toggle-all');
  mark.checked = true;
  mark.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

Then('every todo is marked completed', function () {
  const items = this.todoItems();
  if (items.length === 0) throw new Error('No todos to check');
  for (const li of items) {
    if (!li.classList.contains('completed')) {
      throw new Error(`Todo "${li.querySelector('label').textContent}" not completed`);
    }
  }
});

Then('the row for {string} is the same DOM element as before the last change', function (title) {
  const before = this._rowsBefore && this._rowsBefore[title];
  if (!before) throw new Error(`No captured row for "${title}" before the last change`);
  const after = this.liByTitle(title);
  if (!after) throw new Error(`Row "${title}" is not present after the change`);
  if (after !== before) {
    throw new Error(`Row "${title}" was rebuilt instead of updated in place`);
  }
});

Then('the checkbox for {string} is hidden', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  const display = this.window.getComputedStyle(li.querySelector('.toggle')).display;
  if (display !== 'none') {
    throw new Error(`Checkbox for "${title}" is not hidden (display: ${display})`);
  }
});

Then('the delete button for {string} is hidden', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  const display = this.window.getComputedStyle(li.querySelector('.destroy')).display;
  if (display !== 'none') {
    throw new Error(`Delete button for "${title}" is not hidden (display: ${display})`);
  }
});

Then('the mark-all control is checked', function () {
  const mark = this.document.querySelector('#toggle-all');
  if (!mark.checked) throw new Error('Mark-all control is not checked');
});

Then('the mark-all control is unchecked', function () {
  const mark = this.document.querySelector('#toggle-all');
  if (mark.checked) throw new Error('Mark-all control is checked');
});

When('the user clears completed todos', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

// ----- Editing todos -----

When('the user double-clicks the todo {string}', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  li.querySelector('label').dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

Then('the todo {string} is in edit mode', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  if (!li.classList.contains('editing')) {
    throw new Error(`Todo "${title}" not in edit mode`);
  }
});

Then('the todo {string} is not in edit mode', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  if (li.classList.contains('editing')) {
    throw new Error(`Todo "${title}" still in edit mode`);
  }
});

When('the user edits the title to {string} and presses Enter', function (text) {
  const li = this.document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo in edit mode');
  const edit = li.querySelector('.edit');
  edit.value = text;
  edit.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }),
  );
});

When('the user edits the title to {string} and blurs the field', function (text) {
  const li = this.document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo in edit mode');
  const edit = li.querySelector('.edit');
  edit.value = text;
  edit.dispatchEvent(new this.window.Event('blur'));
});

When('the user edits the title to {string} and presses Escape', function (text) {
  const li = this.document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo in edit mode');
  const edit = li.querySelector('.edit');
  edit.value = text;
  edit.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }),
  );
});

// ----- List summary and visibility -----

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  if (!main.hasAttribute('hidden')) throw new Error('Main section is not hidden');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  if (!footer.hasAttribute('hidden')) throw new Error('Footer is not hidden');
});

Then('the page contains a new todo input', function () {
  if (!this.newTodoInput()) throw new Error('No new todo input present');
});

Then('the page contains a toggle-all control', function () {
  if (!this.document.querySelector('#toggle-all')) throw new Error('No toggle-all control present');
});

Then(
  'the page contains {string}, {string}, and {string} filter links',
  function (a, b, c) {
    const want = [a, b, c];
    const links = Array.from(this.document.querySelectorAll('.filters a'));
    for (const t of want) {
      if (!links.some((l) => l.textContent.trim() === t)) {
        throw new Error(`No filter link "${t}" present`);
      }
    }
  },
);

Then('the remaining count reads {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  const actual = count.textContent.replace(/\s+/g, ' ').trim();
  if (actual !== text) {
    throw new Error(`Remaining count reads "${actual}", expected "${text}"`);
  }
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn.hasAttribute('hidden')) throw new Error('Clear-completed button is not hidden');
});

Then('the clear-completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn.hasAttribute('hidden')) throw new Error('Clear-completed button is hidden');
});

// ----- Persistence -----

When('the user reloads the app', function () {
  this.reloadApp();
});

Then('the {string} localStorage entry is a JSON array', function (key) {
  const raw = this.window.localStorage.getItem(key);
  if (raw == null) throw new Error(`localStorage key "${key}" missing`);
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(`"${key}" is not valid JSON: ${e.message}`);
  }
  if (!Array.isArray(parsed)) throw new Error(`"${key}" is not a JSON array`);
});

Then(/^each stored todo has the fields (.+)$/, function (fieldsRaw) {
  const fields = (fieldsRaw.match(/"([^"]+)"/g) || []).map((s) => s.slice(1, -1));
  const raw = this.window.localStorage.getItem('todos-vanillajs');
  const parsed = JSON.parse(raw);
  for (const todo of parsed) {
    for (const f of fields) {
      if (!(f in todo)) {
        throw new Error(`Stored todo missing field "${f}": ${JSON.stringify(todo)}`);
      }
    }
  }
});

// ----- Routing and filters -----

When('the user opens the {string} filter', function (name) {
  const map = { All: '#/', Active: '#/active', Completed: '#/completed' };
  const hash = map[name] || '#/';
  this.window.location.hash = hash;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

Then('the {string} filter link is selected', function (name) {
  const link = this.filterLink(name);
  if (!link) throw new Error(`No filter link "${name}"`);
  if (!link.classList.contains('selected')) {
    throw new Error(`Filter link "${name}" is not selected`);
  }
});

Then('the {string} filter link is not selected', function (name) {
  const link = this.filterLink(name);
  if (!link) throw new Error(`No filter link "${name}"`);
  if (link.classList.contains('selected')) {
    throw new Error(`Filter link "${name}" is selected`);
  }
});

